import crypto from 'crypto';

export function generateNonce(): string {
  return crypto.randomBytes(16).toString('base64');
}

export const CSP_CONFIG = {
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: [
      "'self'",
      (req: any, res: any) => `'nonce-${res.locals.cspNonce}'`,
    ],
    styleSrc: [
      "'self'",
